_default_html:
	.ascii "<!doctype html><html><head><title>GLIC80</title><style>h1{te"
	.ascii "xt-transform:uppercase;margin-bottom:8px;}h2{margin-top:16px"
	.ascii ";text-transform:uppercase;}p{margin-bottom:8px;}blockquote{m"
	.ascii "argin-left:16px;border:1px solid white;}pre{white-space:pre;"
	.ascii "border:1px solid white;margin-top:8px;}</style></head><body>"
	.ascii "<h1>Mini Browser</h1><p style="
	.db 0x22
	.ascii "font-weight:bold"
	.db 0x22
	.ascii ">This GLIC80 app renders a small useful subset of HTML and C"
	.ascii "SS.</p><p>The virtual document is sixty four text columns wi"
	.ascii "de, exactly four times the screen width. Use left and right "
	.ascii "to pan across wide layouts, and up and down to move through "
	.ascii "the page.</p><h2>Supported HTML</h2><ul><li>Headings, paragr"
	.ascii "aphs, divs, spans and links.</li><li>Lists, blockquotes, pre"
	.ascii "/code, line breaks and rules.</li><li>Images render as compa"
	.ascii "ct text placeholders.</li></ul><blockquote style="
	.db 0x22
	.ascii "padding-left:8px"
	.db 0x22
	.ascii ">CSS is monochrome here, so borders, spacing, hidden content"
	.ascii ", preformatted text and bold/uppercase are mapped onto text."
	.ascii "</blockquote><h2>Wide page test</h2><p>Column 00........10.."
	.ascii "......20........30........40........50........60.</p><pre>bo"
	.ascii "dy { width: 512px; }"
	.db 0x0a
	.ascii ".card { margin-left: 16px; border: 1px solid; }"
	.db 0x0a
	.ascii "&lt;p&gt;HTML entities are decoded.&lt;/p&gt;</pre><p style="
	.db 0x22
	.ascii "margin-left:24px"
	.db 0x22
	.ascii ">Indented content proves that CSS spacing moves with horizon"
	.ascii "tal scroll.</p><p>To load your own site, place HTM1 plus a t"
	.ascii "wo byte length at 0x6000 and the HTML bytes at 0x6006, or re"
	.ascii "place the default_html string and rebuild.</p><hr><p>End of "
	.ascii "demo page.</p></body></html>"
	.db 0x00
